using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoffeeOpenRoadsideVerify{static CoffeeOpenRoadsideVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoffeeOpenRoadsideVerify.request"))return;File.Delete("CoffeeOpenRoadsideVerify.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Coffee Shop Open Roadside Logos");var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);foreach(Transform sign in root.transform){var n=sign.forward;var right=sign.right;var center=sign.position;capture.Invoke(null,new object[]{scene,center+n*20+right*9+Vector3.up*3,center+Vector3.down*2,"Coffee-Open-"+sign.name.Split(')')[0].Replace("billboard (","")+"-Front"});capture.Invoke(null,new object[]{scene,center-n*20-right*9+Vector3.up*3,center+Vector3.down*2,"Coffee-Open-"+sign.name.Split(')')[0].Replace("billboard (","")+"-Back"});}var shops=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>new[]{"Circus_Circus_0 (1)","Circus_Circus_0 (2)"}.Contains(f.name)).OrderByDescending(f=>f.transform.position.x).ToArray();for(int i=0;i<shops.Length;i++){var center=shops[i].GetComponent<Renderer>().bounds.center;foreach(float side in new[]{-1f,1f})capture.Invoke(null,new object[]{scene,new Vector3(center.x+16,34,center.z+side*40),new Vector3(center.x,32,center.z+side*27),"Coffee-Old-Green-Board-Removed-"+(i+1)+(side>0?"-Front":"-Back")});}File.WriteAllText("FinalEnvironmentRoadReview/CoffeeOpenRoadsideVerified.txt","SUCCESS 2 open roadside signs captured on both sides, 4 old green cafe board positions captured. Shared sign mesh assets="+root.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh).Distinct().Count()+"; shared existing materials="+root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().Count()+"; new realtime lights="+root.GetComponentsInChildren<Light>(true).Length+"; shader errors="+root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().Any(m=>ShaderUtil.ShaderHasError(m.shader)));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoffeeOpenRoadsideVerified.txt",e.ToString());Debug.LogException(e);}}}
